import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Thermometer, Droplets, Radar as RadarIcon, Wifi } from 'lucide-react';
import SensorDashboardHeader from './components/SensorStation/SensorHeader';
import TemperatureCard from './components/SensorStation/TemperatureCard';
import HumidityCard from './components/SensorStation/HumidityCard';
import RadarCard from './components/SensorStation/RadarCard';

// ---------------------------------------------------------------------------
// Sensor Station — live dashboard for a DHT-style temp/humidity sensor and a
// PIR motion detector.
//
// This component SIMULATES sensor data locally so it works standalone. To
// wire it to a real device, replace the `pollSensors()` function below with
// a fetch() call to your device's API / MQTT bridge, e.g.:
//
//   async function pollSensors() {
//     const res = await fetch('/api/sensors/latest');
//     return await res.json(); // { temperature, humidity, motion }
//   }
//
// and call `applyReading(data)` with the result on an interval.
// ---------------------------------------------------------------------------


function formatClock(d) {
  return d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
}

export default function SensorDashboard() {
  const [now, setNow] = useState(new Date());
  const [temp, setTemp] = useState(22.4);
  const [hum, setHum] = useState(47.5);
  const [tempHistory, setTempHistory] = useState([22.4]);
  const [humHistory, setHumHistory] = useState([47.5]);
  const [tempMinMax, setTempMinMax] = useState([22.4, 22.4]);
  const [humMinMax, setHumMinMax] = useState([47.5, 47.5]);
  const [motionActive, setMotionActive] = useState(false);
  const [lastMotion, setLastMotion] = useState(null);
  const [motionLog, setMotionLog] = useState([]);
  const [connected, setConnected] = useState(true);
  const motionTimeout = useRef(null);

  const applyReading = useCallback((data) => {
    if (typeof data.temperature === 'number') {
      setTemp(data.temperature);
      setTempHistory((h) => [...h.slice(-(HISTORY_LEN - 1)), data.temperature]);
      setTempMinMax(([mn, mx]) => [Math.min(mn, data.temperature), Math.max(mx, data.temperature)]);
    }
    if (typeof data.humidity === 'number') {
      setHum(data.humidity);
      setHumHistory((h) => [...h.slice(-(HISTORY_LEN - 1)), data.humidity]);
      setHumMinMax(([mn, mx]) => [Math.min(mn, data.humidity), Math.max(mx, data.humidity)]);
    }
    if (data.motion) {
      const t = Date.now();
      setMotionActive(true);
      setLastMotion(t);
      setMotionLog((log) => [...log, t].filter((ts) => t - ts < MOTION_WINDOW_MS));
      clearTimeout(motionTimeout.current);
      motionTimeout.current = setTimeout(() => setMotionActive(false), 4000);
    }
  }, []);

  // --- Simulated sensor feed. Swap this block for a real API poll. ---
  useEffect(() => {
    const tick = setInterval(() => {
      setNow(new Date());
      const nextTemp = Math.min(27, Math.max(18, temp + (Math.random() - 0.5) * 0.3));
      const nextHum = Math.min(65, Math.max(30, hum + (Math.random() - 0.5) * 1.2));
      const motionEvent = Math.random() < 0.06;
      applyReading({ temperature: nextTemp, humidity: nextHum, motion: motionEvent });
    }, 1800);
    return () => clearInterval(tick);
  }, [temp, hum, applyReading]);

  useEffect(() => {
    const flicker = setInterval(() => {
      setConnected(Math.random() > 0.03);
    }, 6000);
    return () => clearInterval(flicker);
  }, []);

  return (
    <div className="ss-root">
      <SensorDashboardHeader/>
      <div className="ss-grid">
        <TemperatureCard/>
        <HumidityCard/>
      </div>
      <RadarCard/>
    </div>
  );
}
